-- Derived metadata only; execute solely on the contained local replay.
WITH targets AS (
 SELECT c.oid,n.nspname,c.relname,c.relowner,c.relacl,c.relrowsecurity,c.relforcerowsecurity
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE c.relkind IN('r','p') AND ((n.nspname='public' AND c.relname IN('fin_ingresos','fin_transacciones_ganado','hato_produccion_quincenal','fin_gastos','compras','hato_capturas_foto','gan_movimientos','gan_inventario','gan_pesos_historico','gan_fincas','gan_potreros','hato_eventos','hato_animales')) OR (n.nspname IN('hato_quincena','hato_income_metadata','invoice_upload','hato_sale')) OR(n.nspname='storage' AND c.relname='objects'))
), roles AS(SELECT unnest(ARRAY['anon','authenticated','service_role']) role), funcs AS(
 SELECT p.*,n.nspname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN('hato_quincena','hato_income_metadata','invoice_upload','hato_sale') OR(n.nspname='public' AND (p.prosrc~'fin_ingresos|fin_transacciones_ganado|hato_produccion_quincenal|hato_income_metadata|hato_quincena|invoice_upload|gan_movimientos|gan_inventario|gan_pesos_historico' OR p.proname~'quincena|income_invoice|income_metadata'))
)
SELECT jsonb_build_object(
 'relations',(SELECT jsonb_agg(jsonb_build_object('schema',nspname,'table',relname,'owner',pg_get_userbyid(relowner),'rls',relrowsecurity,'force_rls',relforcerowsecurity,'acl',relacl) ORDER BY nspname,relname) FROM targets),
 'effective_table_acl',(SELECT jsonb_agg(jsonb_build_object('schema',nspname,'table',relname,'role',role,'select',has_table_privilege(role,oid,'SELECT'),'insert',has_table_privilege(role,oid,'INSERT'),'update',has_table_privilege(role,oid,'UPDATE'),'delete',has_table_privilege(role,oid,'DELETE'),'truncate',has_table_privilege(role,oid,'TRUNCATE')) ORDER BY nspname,relname,role) FROM targets CROSS JOIN roles),
 'effective_column_acl',(SELECT jsonb_agg(jsonb_build_object('schema',t.nspname,'table',t.relname,'column',a.attname,'role',role,'acl',a.attacl,'select',has_column_privilege(role,t.oid,a.attnum,'SELECT'),'insert',has_column_privilege(role,t.oid,a.attnum,'INSERT'),'update',has_column_privilege(role,t.oid,a.attnum,'UPDATE')) ORDER BY t.nspname,t.relname,a.attnum,role) FROM targets t JOIN pg_attribute a ON a.attrelid=t.oid AND a.attnum>0 AND NOT a.attisdropped CROSS JOIN roles),
 'functions',(SELECT jsonb_agg(jsonb_build_object('identity',f.oid::regprocedure::text,'owner',pg_get_userbyid(f.proowner),'security_definer',f.prosecdef,'configuration',f.proconfig,'acl',f.proacl,'body_md5',md5(f.prosrc),'effective_execute',(SELECT jsonb_object_agg(role,has_function_privilege(role,f.oid,'EXECUTE')) FROM roles)) ORDER BY f.nspname,f.proname,pg_get_function_identity_arguments(f.oid)) FROM funcs f),
 'trigger_bindings',(SELECT jsonb_agg(jsonb_build_object('schema',t.nspname,'table',t.relname,'name',g.tgname,'enabled',g.tgenabled,'definition_md5',md5(pg_get_triggerdef(g.oid)),'function',g.tgfoid::regprocedure::text) ORDER BY t.nspname,t.relname,g.tgname) FROM targets t JOIN pg_trigger g ON g.tgrelid=t.oid AND NOT g.tgisinternal),
 'outgoing_fks',(SELECT jsonb_agg(jsonb_build_object('from',conrelid::regclass::text,'to',confrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(k.oid),'validated',convalidated,'deferrable',condeferrable,'deferred',condeferred) ORDER BY conrelid::regclass::text,conname) FROM pg_constraint k WHERE contype='f' AND conrelid IN(SELECT oid FROM targets)),
 'incoming_fks',(SELECT jsonb_agg(jsonb_build_object('from',conrelid::regclass::text,'to',confrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(k.oid),'validated',convalidated,'deferrable',condeferrable,'deferred',condeferred) ORDER BY conrelid::regclass::text,conname) FROM pg_constraint k WHERE contype='f' AND confrelid IN(SELECT oid FROM targets)),
 'policies',(SELECT jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'permissive',permissive,'roles',p.roles,'command',cmd,'using',qual,'check',with_check) ORDER BY schemaname,tablename,policyname) FROM pg_policies p JOIN targets t ON t.nspname=p.schemaname AND t.relname=p.tablename));
